            self.save()
            return True

    def remove_account(self, label: str) -> bool:
        with self.lock:
            before = len(self.accounts)
            self.accounts = [a for a in self.accounts if a.account_label != label]
            if len(self.accounts) < before:
                self.save()
                return True
            return False

